  if(value.getClass()==BigDecimal.class){r.put("projection","decimal-int");if(!(wire instanceof Number)||new BigDecimal(wire.toString()).compareTo((BigDecimal)value)!=0)throw new IllegalStateException("Numeric projection differs");}
